# ---- input helpers ----
def get_int(prompt, low, high):
    """Keep asking until a whole number from low to high is typed; return it."""
    while True:
        text = input(prompt)
        if not text.isdigit():
            print("Please type a whole number.")
        elif int(text) < low or int(text) > high:
            print("Must be from", low, "to", high)
        else:
            return int(text)

def get_text(prompt):
    """Keep asking until something other than blank is typed; return it stripped."""
    while True:
        text = input(prompt).strip()
        if text != "":
            return text
        print("This cannot be blank.")

