def load_members(filename):
    """Return a list of [name, year, points] read from filename; empty list if missing."""
    members = []
    try:
        with open(filename) as f:
            for line in f:
                line = line.strip()
                if line != "":
                    parts = line.split(",")
                    members.append([parts[0], int(parts[1]), int(parts[2])])
    except FileNotFoundError:
        pass
    return members

def save_members(members, filename):
    """Write every record to filename as name,year,points, replacing the file."""
    with open(filename, "w") as f:
        for m in members:
            f.write(m[0] + "," + str(m[1]) + "," + str(m[2]) + "\n")

# ---- register operations ----
def find_member(members, name):
    """Return the index of the member called name, or -1."""
    for i in range(len(members)):
        if members[i][0] == name:
            return i
    return -1

def format_member(m):
    """Return the display line for one member."""
    return m[0] + " (year " + str(m[1]) + ") - " + str(m[2]) + " points"

def show_all(members):
    """Print one line per member, or 'No members'."""
    if len(members) == 0:
        print("No members")
    for m in members:
        print(format_member(m))

def add_member(members):
    """Ask for name and year, append a new record with 0 points. Names must be unique."""
    name = get_text("Name: ")
    if find_member(members, name) != -1:
        print("That name is already in the register")
        return
    year = get_int("Year group (7-11): ", MIN_YEAR, MAX_YEAR)
    members.append([name, year, 0])
    print("Added", name)

def show_member(members):
    """Ask for a name and print that member's details or 'Not found'."""
    name = get_text("Name: ")
    i = find_member(members, name)
    if i == -1:
        print("Not found")
    else:
        print(format_member(members[i]))

def award_points(members):
    """Ask for a name and points (1-100); add the points to that member."""
    name = get_text("Name: ")
    i = find_member(members, name)
    if i == -1:
        print("Not found")
        return
    points = get_int("Points to add (1-100): ", 1, MAX_POINTS)
    members[i][2] = members[i][2] + points
    print(name, "now has", members[i][2], "points")

def remove_member(members):
    """Ask for a name and delete that member, or print 'Not found'."""
    name = get_text("Name to remove: ")
    i = find_member(members, name)
    if i == -1:
        print("Not found")
    else:
